package deps

import (
	"fmt"
	"strings"

	"github.com/parsabordbar/ctx3/skillwriter"
)

// moduleBase returns the last path element of the module path, used as a
// human-friendly project name in skill naming and prose.
func moduleBase(module string) string {
	if i := strings.LastIndex(module, "/"); i >= 0 {
		return module[i+1:]
	}
	return module
}

// Skill builds a fact-only progressive-disclosure skill describing this
// module's dependency chain. The SKILL.md carries a sharp trigger; the full
// graph (Markdown + TOON) lives in reference files loaded on demand.
func (g *Graph) Skill() skillwriter.Skill {
	base := moduleBase(g.Module)

	desc := fmt.Sprintf(
		"Internal dependency chain of the %s project: which packages import which, "+
			"their external dependencies, and any circular imports. Use when asked about "+
			"dependencies, what imports or depends on a package, coupling between packages, "+
			"import cycles, or safe refactor/extraction order.",
		base)

	cycleNote := "No circular imports were detected."
	if len(g.Cycles) > 0 {
		cycleNote = fmt.Sprintf("**%d circular import(s) detected** — see the reference for the exact chains.", len(g.Cycles))
	}

	overview := fmt.Sprintf(
		"Dependency facts for `%s` (%d internal packages), generated by `ctx3 deps`.\n\n%s",
		g.Module, len(g.Order), cycleNote)

	return skillwriter.Skill{
		Name:        base + "-deps",
		Description: desc,
		Overview:    overview,
		References: []skillwriter.Reference{
			{
				Filename: "dependencies.md",
				When:     "you need the full internal import graph, external deps, or cycle chains",
				Content:  RenderText(g),
			},
			{
				Filename: "dependencies.mermaid.md",
				When:     "you want to visualize the dependency graph as a diagram",
				Content:  RenderMermaid(g),
			},
		},
	}
}
